using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using Autodesk.Revit.ApplicationServices;
using Autodesk.Revit.DB;
using RevitMcpNext.Addin.Ipc;

namespace RevitMcpNext.Addin
{
    /// <summary>
    /// dev.dump_labels (SPEC §9.7, internal key): the English alias tables Common/Aliases/aliases-&lt;year&gt;.json are
    /// generated by running this op in Revit started with /language ENU. LabelUtils.GetLabelFor gives the UI label of
    /// every BuiltInCategory and BuiltInParameter; categories with the same label prefer the one present in the open
    /// document. The file is written to &lt;home&gt;\logs\aliases-&lt;year&gt;-&lt;language&gt;.json (copy it over the seed to
    /// ship it); inline:true also returns the tables. On a non-English UI the labels are localized: the result says so,
    /// and the e2e S21 scenario compares the shipped table with them instead.
    /// </summary>
    internal static class DumpLabelOps
    {
        [Op("dev.dump_labels", Kind = "read", Scope = "none", Idle = true)]
        public static OpResult DumpLabels(RequestContext ctx)
        {
            Application app = ctx.RevitApp ?? throw new OpException(ErrorCodes.RevitStarting, "The add-in is still starting.");
            string language = app.Language.ToString();
            Document doc = ctx.Doc;
            if (doc == null)
            {
                try { doc = ctx.App?.ActiveUIDocument?.Document; } catch { doc = null; }
            }
            var present = new HashSet<BuiltInCategory>();
            var topLevel = new HashSet<BuiltInCategory>();
            if (doc != null)
            {
                foreach (Category category in doc.Settings.Categories)
                {
                    BuiltInCategory builtIn = Resolve.SafeBuiltIn(category);
                    if (builtIn != BuiltInCategory.INVALID)
                    {
                        present.Add(builtIn);
                        topLevel.Add(builtIn);
                    }
                    try
                    {
                        foreach (Category sub in category.SubCategories)
                        {
                            BuiltInCategory subBuiltIn = Resolve.SafeBuiltIn(sub);
                            if (subBuiltIn != BuiltInCategory.INVALID) present.Add(subBuiltIn);
                        }
                    }
                    catch
                    {
                        // No subcategories.
                    }
                }
            }

            // Categories: label → best category.
            var categories = new Dictionary<string, BuiltInCategory>(StringComparer.Ordinal);
            int categoryLabels = 0;
            // Only categories the document really has: LabelUtils on a stale BuiltInCategory enum value can fail in native
            // code (an access violation that .NET 10 cannot catch, which took Revit 2027 down in e2e S21).
            if (doc == null) throw new OpException(ErrorCodes.NoOpenDocument, "dev.dump_labels needs an open project document.");
            foreach (BuiltInCategory category in present.OrderBy(c => (long)c))
            {
                if (category == BuiltInCategory.INVALID) continue;
                string label = CategoryLabel(category, doc);
                if (string.IsNullOrWhiteSpace(label) || label == category.ToString()) continue;
                label = label.Trim();
                categoryLabels++;
                if (!categories.TryGetValue(label, out BuiltInCategory existing) || Better(category, existing, present, topLevel))
                {
                    categories[label] = category;
                }
            }

            // Parameters: label → every built-in with that label (the one present on the element wins at runtime).
            var parameters = new Dictionary<string, List<string>>(StringComparer.Ordinal);
            int parameterLabels = 0;
            // Revit's own list of valid built-in parameters (2022+), never the raw enum (same native-crash risk as above).
            foreach (ForgeTypeId parameterId in ParameterUtils.GetAllBuiltInParameters())
            {
                BuiltInParameter parameter;
                try { parameter = ParameterUtils.GetBuiltInParameter(parameterId); } catch { continue; }
                if (parameter == BuiltInParameter.INVALID) continue;
                string label;
                try { label = LabelUtils.GetLabelForBuiltInParameter(parameterId); } catch { label = null; }
                if (string.IsNullOrWhiteSpace(label) || label == parameter.ToString()) continue;
                label = label.Trim();
                parameterLabels++;
                if (!parameters.TryGetValue(label, out List<string> list)) parameters[label] = list = new List<string>();
                string token = parameter.ToString();
                if (!list.Contains(token)) list.Add(token);
            }

            var table = new Dictionary<string, object>(StringComparer.Ordinal)
            {
                ["schema"] = 1,
                ["source"] = "dev.dump_labels, Revit " + ctx.Year.ToString(CultureInfo.InvariantCulture) + " " + SafeBuild(app) + ", language " + language,
                ["categories"] = categories.OrderBy(p => p.Key, StringComparer.Ordinal).ToDictionary(p => p.Key, p => (object)p.Value.ToString()),
                ["parameters"] = parameters.OrderBy(p => p.Key, StringComparer.Ordinal).ToDictionary(p => p.Key, p => (object)p.Value.Cast<object>().ToList())
            };

            string path = null;
            try
            {
                string dir = ctx.Home?.LogsDir;
                if (!string.IsNullOrEmpty(dir))
                {
                    Directory.CreateDirectory(dir);
                    path = Path.Combine(dir, "aliases-" + ctx.Year.ToString(CultureInfo.InvariantCulture) + "-" + language + ".json");
                    File.WriteAllText(path, JsonWireCodec.Serialize(table));
                }
            }
            catch (Exception ex)
            {
                ctx.Warn(WarningCodes.PartialResult, "could not write the alias file: " + ex.Message);
                path = null;
            }

            bool english = language.StartsWith("English", StringComparison.OrdinalIgnoreCase);
            var data = new Dictionary<string, object>(StringComparer.Ordinal)
            {
                ["language"] = language,
                ["english"] = english,
                ["path"] = path,
                ["categories"] = categories.Count,
                ["parameters"] = parameters.Count,
                ["category_labels"] = categoryLabels,
                ["parameter_labels"] = parameterLabels,
                ["doc"] = doc?.Title
            };
            if (ctx.Args.Bool("inline")) data["table"] = table;
            string summary = categories.Count.ToString(CultureInfo.InvariantCulture) + " category and " + parameters.Count.ToString(CultureInfo.InvariantCulture) +
                             " parameter labels (" + language + ")" + (english ? string.Empty : " - not English: do not ship this table");
            return OpResult.Success(data, summary);
        }

        private static string CategoryLabel(BuiltInCategory category, Document doc)
        {
            try
            {
                string label = LabelUtils.GetLabelFor(category);
                if (!string.IsNullOrWhiteSpace(label)) return label;
            }
            catch
            {
                // Fall back to the document's category name.
            }
            if (doc == null) return null;
            try { return Category.GetCategory(doc, category)?.Name; } catch { return null; }
        }

        /// <summary>Top-level categories of the document beat subcategories, which beat absent ones; then the shorter token.</summary>
        private static bool Better(BuiltInCategory candidate, BuiltInCategory existing, HashSet<BuiltInCategory> present, HashSet<BuiltInCategory> topLevel)
        {
            int Rank(BuiltInCategory c) => topLevel.Contains(c) ? 2 : present.Contains(c) ? 1 : 0;
            int a = Rank(candidate), b = Rank(existing);
            if (a != b) return a > b;
            int la = candidate.ToString().Length, lb = existing.ToString().Length;
            if (la != lb) return la < lb;
            return string.CompareOrdinal(candidate.ToString(), existing.ToString()) < 0;
        }

        private static string SafeBuild(Application app)
        {
            try { return app.VersionBuild; } catch { return string.Empty; }
        }
    }
}
